// Errors and warnings the Entra Connect Sync servers wrote to their Application log in the last day, sent to the
// Event table by the Azure Monitor Agent. Learn doesn't list the synchronization service's run-profile event IDs,
// so the query keeps every error and warning from the sources the SyncEventSources parameter names.
Event
| where TimeGenerated > ago(1d)
| where Computer in ({SyncServers})
| where EventLog == "Application" and Source in ({SyncEventSources})
| where EventLevelName in ("Error", "Warning")
| summarize Count = count(), LastSeen = max(TimeGenerated), Sample = take_any(RenderedDescription) by Computer, Source, EventID, EventLevelName
| order by LastSeen desc

// One row per synchronization server: when its Azure Monitor Agent last sent a heartbeat, and its latest backup
// event (the BackupEventSources parameter). A server missing from Heartbeat, or with no backup event, shows
// with an empty time, which the tab flags: a silent server never reads as healthy.
let servers = dynamic([{SyncServers}]);
let beats = Heartbeat
    | where TimeGenerated > ago(2d)
    | where Computer in (servers)
    | summarize LastHeartbeat = max(TimeGenerated) by Computer;
let backups = Event
    | where TimeGenerated > ago(2d)
    | where Computer in (servers) and Source in ({BackupEventSources})
    | summarize arg_max(TimeGenerated, EventID, EventLevelName) by Computer
    | project Computer, LastBackupEvent = TimeGenerated, BackupEventID = EventID, BackupLevel = EventLevelName;
print Computer = servers
| mv-expand Computer to typeof(string)
| join kind=leftouter beats on Computer
| join kind=leftouter backups on Computer
| extend HeartbeatLimitMin = 60, BackupLimitMin = 1560
| project Computer, LastHeartbeat, HeartbeatLimitMin, LastBackupEvent, BackupEventID, BackupLevel, BackupLimitMin
| order by Computer asc

// One row per domain controller and when its Azure Monitor Agent last sent a heartbeat (Learn's "Unavailable
// computers" pattern, by the DomainControllers parameter). A controller with no heartbeat shows with an empty time.
let dcs = dynamic([{DomainControllers}]);
let beats = Heartbeat
    | where TimeGenerated > ago(1d)
    | where Computer in (dcs)
    | summarize LastHeartbeat = max(TimeGenerated) by Computer;
print Computer = dcs
| mv-expand Computer to typeof(string)
| join kind=leftouter beats on Computer
| extend HeartbeatLimitMin = 60
| project Computer, LastHeartbeat, HeartbeatLimitMin
| order by Computer asc

// Every replication link from the probe's latest run (repadmin /showrepl * /csv, written through the Logs
// Ingestion API). A link whose last attempt failed is "failing"; no run in two days leaves the tab stale.
let lastRun = toscalar(DcReplicationProbe_CL | where TimeGenerated > ago(2d) | summarize max(TimeGenerated));
DcReplicationProbe_CL
| where TimeGenerated > ago(2d) and TimeGenerated == lastRun
| project TimeGenerated, DestinationDc, SourceDc, NamingContext, Failures, LastSuccessUtc, LastFailureUtc, LastFailureStatus, Verdict
| order by Verdict asc, DestinationDc asc, SourceDc asc

// The security events Microsoft rates High (a single occurrence is investigated), and 1102, on the domain
// controllers in the last day. The list is Book 12, Chapter 03's; the Windows Security Events via AMA
// connector writes them to SecurityEvent when its event set includes them.
SecurityEvent
| where TimeGenerated > ago(1d)
| where Computer in ({DomainControllers})
| where EventID in (1102, 4618, 4649, 4719, 4765, 4766, 4794, 4897, 4964, 5124)
| summarize Count = count(), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by Computer, EventID, Activity
| order by LastSeen desc

// Directory Service, DFS Replication (SYSVOL) and DNS Server events on the domain controllers in the last day:
// the replication and SYSVOL events Learn's troubleshooting articles name (1311, 1925, 1988, 2042, 2213, 4012,
// 4013), and every error. Sent to the Event table by the Azure Monitor Agent's data collection rule.
Event
| where TimeGenerated > ago(1d)
| where Computer in ({DomainControllers})
| where EventID in (1311, 1925, 1988, 2042, 2213, 4012, 4013) or EventLevelName == "Error"
| summarize Count = count(), LastSeen = max(TimeGenerated), Sample = take_any(RenderedDescription) by Computer, EventLog, Source, EventID, EventLevelName
| order by LastSeen desc

// Microsoft's emergency access sign-in query (Manage emergency access admin accounts), with the accounts'
// object IDs from the EmergencyAccessIds parameter instead of literals. The alert rule is the control.
let ids = dynamic([{EmergencyAccessIds}]);
SigninLogs
| where TimeGenerated > ago(1d)
| where UserId in (ids)
| project TimeGenerated, UserPrincipalName, UserId, IPAddress, ResultType, ResultDescription
| order by TimeGenerated desc

// Request-driven Entra changes in the last day, by Learn's audit activity names: password resets, authentication
// methods an administrator registered, updated or deleted, accounts created, users updated by an application
// (the catalog's scripts act through Graph), and custom role definitions. Consents and role assignments are on
// the grants tab. Matching each row to its ticket happens in the ITSM tool, not here.
AuditLogs
| where TimeGenerated > ago(1d)
| where ActivityDisplayName in ("Reset password (by admin)", "Reset password", "Admin started password reset", "Admin registered security info", "Admin updated security info", "Admin deleted security info", "Add user", "Add role definition", "Update role definition")
    or (ActivityDisplayName == "Update user" and isnotempty(tostring(InitiatedBy.app.displayName)))
| extend Actor = coalesce(tostring(InitiatedBy.user.userPrincipalName), tostring(InitiatedBy.app.displayName))
| extend Target = coalesce(tostring(TargetResources[0].userPrincipalName), tostring(TargetResources[0].displayName))
| project TimeGenerated, ActivityDisplayName, Actor, Target, Result, CorrelationId
| order by TimeGenerated desc
